import json, time

async def main(args):
    raw = args.params.get("cache_raw")
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = {}
    if not isinstance(raw, dict):
        raw = {}
    hit = raw.get("hit")
    val = raw.get("value")
    fresh, text = False, ""
    try:
        if hit and val:
            d = json.loads(val) if isinstance(val, str) else val
            ts = float((d or {}).get("ts") or 0)
            if time.time() - ts < 300 and (d or {}).get("text"):
                fresh, text = True, d["text"]
    except Exception:
        fresh = False
    return {"fresh": fresh, "text": text}

import json, time

async def main(args):
    raw = args.params.get("raw")
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = {}
    if not isinstance(raw, dict):
        raw = {}
    items = raw.get("data") or []
    STATUS = {"Running": "🟢运行中", "Terminated": "⚫已关机", "Stopped": "⚫已关机",
              "Creating": "🟡创建中", "Starting": "🟡启动中", "Stopping": "🟡停止中"}
    lines, running = [], 0
    for it in items:
        st = str(it.get("notebookStatus") or "?")
        if st == "Running":
            running += 1
        mark = STATUS.get(st, "❔" + st)
        name = it.get("notebookName") or "?"
        img = (str(it.get("imageName") or "").split(":")[0])[:44]
        grp = it.get("resourceGroupId") or "?"
        acc = "%s卡/%s/%s" % (it.get("acceleratorNumber") or 1, it.get("cpuNumber") or "?",
                              it.get("ramSize") or "?")
        upd = str(it.get("updateTime") or "")[5:16]
        cmd = str(it.get("command") or "").strip()
        duty = ""
        if "monitor.py" in cmd:
            seg = ""
            if "--ids" in cmd:
                seg = cmd.split("--ids", 1)[1].split("--")[0].strip().strip(",")
            n = len([x for x in seg.split(",") if x.strip()])
            duty = " · 在跑 monitor（%s）" % ("监控 %d 个任务" % n if n else "常驻监控")
        elif "comfy" in cmd.lower():
            duty = " · 在跑 ComfyUI 服务"
        elif cmd:
            duty = " · 命令: " + cmd[:80]
        lines.append("  卡组%s %s %s（%s · %s · 更新%s）%s" % (grp, mark, name, acc, img, upd, duty))
    if not lines:
        text = "（SCNet 当前区域无实例）"
    else:
        head = "[SCNet 容器状态 · %s] 共 %d 个实例，运行中 %d 个" % (
            time.strftime("%m-%d %H:%M"), len(items), running)
        tail = ("（有运行中实例：可用 scnet_comfy(action='stats') / scnet_monitor(action='status') "
                "查其内部任务详情）") if running else "（当前无运行中实例）"
        text = head + "\n" + "\n".join(lines) + "\n" + tail
    payload = json.dumps({"ts": time.time(), "text": text}, ensure_ascii=False)
    return {"status_text": text, "cache_payload": payload}
